 parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--url',default='http://127.0.0.1:18765/app/');parser.add_argument('--report',type=Path,default=ROOT/'docs/validation/country-refinement-local.json');parser.add_argument('--provisional',action='store_true',help='Mark a trial against an intermediate data build.');args=parser.parse_args();report=args.report.resolve();report.parent.mkdir(parents=True,exist_ok=True);prefix=report.stem;checks=[];errors=[];screenshots=[];versions={};assets=[];started=time.monotonic()
